import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for SingularValueDecompositionImpl.getU()
 */
public class SingularValueDecompositionImpl_getU_TriageGen2Test {





    /**
     * Test case to verify the caching mechanism.
     * Calling getU() multiple times should return the same object instance.
     */
    @Test
    public void testGetU_CachingMechanism() throws InvalidMatrixException {
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u1 = svd.getU();
        RealMatrix u2 = svd.getU();

        assertNotNull(u1);
        assertSame("The second call to getU() should return the cached instance", u1, u2);
    }


}

